// Generates public/static/clerk-id.js from @clerk/localizations (idID) so the
// customer page can localize Clerk UI without inline scripts (CSP-compatible).
import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
const { idID } = createRequire(import.meta.url)("@clerk/localizations");
writeFileSync(
  "public/static/clerk-id.js",
  "// Generated by scripts/build-clerk-locale.mjs from @clerk/localizations (idID).\nwindow.HIO_CLERK_LOCALE = " +
    JSON.stringify(idID) +
    ";\n",
);
console.log("clerk-id.js written");
